/* Density variations */

:root {
  /* XS - 12x12px icons */
  --icon-ascending-xs: url("chrome://messenger/skin/icons/xs/ascending.svg");
  --icon-close-xs: url("chrome://messenger/skin/icons/xs/close.svg");
  --icon-descending-xs: url("chrome://messenger/skin/icons/xs/descending.svg");
  --icon-dot-xs: url("chrome://messenger/skin/icons/xs/dot.svg");
  --icon-nav-down-xs: url("chrome://messenger/skin/icons/new/nav-down-xs.svg");
  --icon-nav-up-xs: url("chrome://messenger/skin/icons/new/nav-up-xs.svg");
  --icon-moon-xs: url("chrome://messenger/skin/icons/new/moon-xs.svg");
  --icon-replies-xs: url("chrome://messenger/skin/icons/xs/replies.svg");
  --icon-sparkle-star-xs: url("chrome://messenger/skin/icons/xs/sparkle-star.svg");
  --icon-sun-xs: url("chrome://messenger/skin/icons/new/sun-xs.svg");

  /* SM - 16x16px icons */
  --icon-folder-compact-sm: url("chrome://messenger/skin/icons/sm/folder-compact.svg");
  --icon-sparkle-star-sm: url("chrome://messenger/skin/icons/sm/sparkle-star.svg");
  --icon-upload-sm: url("chrome://messenger/skin/icons/sm/upload.svg");
  --icon-mail-list: url("chrome://messenger/skin/icons/new/compact/user-list-alt.svg");
  --icon-maximize-sm: url("chrome://messenger/skin/icons/sm/maximize.svg");
  --icon-minimize-sm: url("chrome://messenger/skin/icons/sm/minimize.svg");
  --icon-mobile-export-sm: url("chrome://messenger/skin/icons/sm/mobile-export.svg");
  --icon-video-sm: url("chrome://messenger/skin/icons/sm/video.svg");

  /* LG - 24x24px icons */
  --icon-mobile-export-lg: url("chrome://messenger/skin/icons/lg/mobile-export.svg");

  --icon-account-settings: url("chrome://messenger/skin/icons/new/compact/account-settings.svg");
  --icon-add: url("chrome://messenger/skin/icons/new/compact/add.svg");
  --icon-address-book: url("chrome://messenger/skin/icons/new/compact/address-book.svg");
  --icon-app-menu: url("chrome://messenger/skin/icons/new/compact/app-menu.svg");
  --icon-app-menu-addon: url("chrome://messenger/skin/icons/new/compact/app-menu-addon.svg");
  --icon-app-menu-badged: url("chrome://messenger/skin/icons/new/compact/app-menu-badged.svg");
  --icon-archive: url("chrome://messenger/skin/icons/new/compact/archive.svg");
  --icon-attachment: url("chrome://messenger/skin/icons/new/compact/attachment.svg");
  --icon-calendar-invite: url("chrome://messenger/skin/icons/new/compact/calendar-invite.svg");
  --icon-calendar-today: url("chrome://messenger/skin/icons/new/compact/calendar-today.svg");
